const viewport=element<HTMLDivElement>('#viewport'),renderer=new WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(1);renderer.setSize(viewport.clientWidth,viewport.clientHeight);renderer.toneMapping=ACESFilmicToneMapping;renderer.toneMappingExposure=1.;viewport.append(renderer.domElement);const scene=new Scene();scene.background=new Color('#edf1f4');const camera=new PerspectiveCamera(42,viewport.clientWidth/viewport.clientHeight,.1,160);scene.add(new HemisphereLight(0xdcefff,0x7f7c70,2.4));const light=new DirectionalLight(0xffffff,3);light.position.set(8,16,4);scene.add(light);const fill=new DirectionalLight(0xffffff,1.2);fill.position.set(-8,10,-12);scene.add(fill);const grid=new GridHelper(40,40,0x9dadb6,0xd3dce3);grid.position.y=-.012;scene.add(grid);const floorGeometry=new PlaneGeometry(50,50),floorMaterial=new MeshStandardMaterial({color:0xe2e8ec,roughness:.95});const floor=new Mesh(floorGeometry,floorMaterial);floor.rotation.x=-Math.PI/2;floor.position.y=-.025;scene.add(floor);
let loaded:LoadedAsset[]=[],cargo:Mesh|undefined,geometry:BufferGeometry|undefined,appearance:MeshStandardMaterial|undefined,operation:Operation|undefined,manifest:AssetManifest|undefined,load:((asset:Asset,lod:Asset['lods'][number],options:LoadOptions)=>Promise<LoadedAsset>)|undefined,lod=0,direction:'load'|'unload'='unload',elapsed=0,playing=false,blocked=false,last=performance.now(),rate=1,ready=false,disposed=false,manifestHash='';
function duration():number{return operation?.phases.reduce((total,p)=>total+p.segments.reduce((s,x)=>s+x.duration_ms,0),0)??0;}
function poseAt(ms:number){if(!operation)throw Error('Source operation missing');let start=0;for(const phase of operation.phases)for(const segment of phase.segments){const end=start+segment.duration_ms;if(ms<=end||end===duration()){const p=Math.max(0,Math.min(1,(ms-start)/segment.duration_ms)),values=Object.fromEntries(segment.channels.map(c=>[c.function_id,c.start_value+(c.end_value-c.start_value)*p]));const center:readonly[number,number,number]=phase.kind==='grip'?[0,2.6,direction==='unload'?0:6]:phase.kind==='release'?[0,2.6,direction==='unload'?6:0]:[0,2.6+values.hoist!,values.bridge_travel!];return{phase:phase.kind,segment:segment.id,progress:p,bridge:values.bridge_travel!,trolley:values.trolley_travel!,hoist:values.hoist!,material:center};}start=end;}throw Error('Uncovered source interval');}
