async function init(){const config=configShape.parse(await(await fetch('/complete-config.json')).json());manifestHash=config.manifestSha;const [loader,parser,factory]=await Promise.all([moduleValue(config.loaderModule,'loadAsset'),moduleValue(config.manifestModule,'parseProductionAssetManifest'),moduleValue(config.factoryModule,'createVersionCoilGeometry')]);if(typeof loader!=='function'||typeof parser!=='function'||typeof factory!=='function')throw Error('Pinned product functions absent');load=loader as NonNullable<typeof load>;manifest=(parser as (text:string)=>AssetManifest)(await(await fetch('/assets/steelworks/transport/manifest.json')).text());const domain=z.object({materials:z.array(MaterialSchema),material_versions:z.array(MaterialVersionSchema)}).parse(await(await fetch('/handling-source-domain.json')).json()),material=domain.materials.find(m=>m.id==='t16:material:1'),version=domain.material_versions.find(v=>v.id===material?.current_version_id);if(!material||!version)throw Error('Exact material version absent');geometry=(factory as (m:typeof material,v:typeof version)=>BufferGeometry)(material,version);appearance=new MeshStandardMaterial({color:0x65859b,metalness:.82,roughness:.3});cargo=new Mesh(geometry,appearance);cargo.name='actual-version-coil';scene.add(cargo);element<HTMLSpanElement>('#material').textContent=`${material.form} · 폭 ${version.dimensions.width_mm}mm · 외경 ${version.dimensions.diameter_mm}mm · 내경 ${version.dimensions.inner_diameter_mm}mm · 두께 ${version.dimensions.thickness_mm}mm · ${version.weight_kg.toLocaleString()}kg`;await select();view('diagonal');let running=true;const loop=(now:number)=>{if(disposed){running=false;return;}if(playing&&!blocked){elapsed=Math.min(duration(),elapsed+(now-last)*rate);if(elapsed===duration())playing=false;}last=now;render();if(running)requestAnimationFrame(loop);};requestAnimationFrame(loop);}
